function band(state,deci){if(state==='buffer_depleted')return'critical';if(state==='no_shortfall')return'clear';if(deci<10)return'critical';if(deci<30)return'storm_warning';if(deci<60)return'watch';if(deci<120)return'fair_skies';return'clear';}
