    for (const input of [null, undefined]) {
      const empty = buildAtlasPlot(input as AtlasEntry[] | null | undefined)
      expect(empty.total).toBe(0)
      expect(empty.dots).toHaveLength(0)
      expect(empty.capBin.count).toBe(0)
    }
  })
