AtlasSection design:
- no props
- reads useConsole (bundle, status, twist, selectAccount)
- ONE useMemo over [bundle, twist]:
  - scenario = shockedAtlasScenario(profiles, twist)
  - summary = summarizeStormAtlas(scenario.entries, { scenarioLabel: scenario.scenarioLabel })
  - baseline = sameTwist ? null : summarizeStormAtlas(shockedAtlasScenario(profiles, IDLE_TWIST).entries)
  - plot = buildAtlasPlot(scenario.entries)
- Slim loading/error states (ConsoleView owns retry)
- Dot click -> selectAccount(id) + scrollIntoView to #console (respect prefers-reduced-motion: auto vs smooth)

Code:

```tsx
import { useMemo } from 'react'
import { useConsole } from '../../state/consoleStore'
import { IDLE_TWIST, sameTwist, type Twist } from '../../lib/shocks'
import { shockedAtlasScenario, summarizeStormAtlas, type StormAtlasSummary } from '../../lib/stormAtlas'
import { buildAtlasPlot, type AtlasPlot } from '../../lib/atlasPlot'
import StormAtlas from './StormAtlas'
import AtlasStripPlot from './AtlasStripPlot'

interface AtlasDerivation {
  summary: StormAtlasSummary
  baseline: StormAtlasSummary | null
  plot: AtlasPlot
}

export default function AtlasSection() {
  const status = useConsole((state) => state.status)
  const bundle = useConsole((state) => state.bundle)
  const twist = useConsole((state) => state.twist)
  const selectedId = useConsole((state) => state.selectedId)
  const selectAccount = useConsole((state) => state.selectAccount)

  const derived = useMemo<AtlasDerivation | null>(() => {
    if (!bundle) return null
    const profiles = Object.values(bundle.profiles)
    const scenario = shockedAtlasScenario(profiles, twist)
    const summary = summarizeStormAtlas(scenario.entries, { scenarioLabel: scenario.scenarioLabel })
    const baseline = sameTwist(twist, IDLE_TWIST)
      ? null
      : summarizeStormAtlas(shockedAtlasScenario(profiles, IDLE_TWIST).entries)
    return { summary, baseline, plot: buildAtlasPlot(scenario.entries) }
  }, [bundle, twist])

  const handleSelect = (id: string): void => {
    selectAccount(id)
    const target = document.getElementById('console')
    if (!target || typeof target.scrollIntoView !== 'function') return
    const reduced = typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches
    target.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' })
  }

  if (status === 'error') {
    return (
      <div className="ax-shell">
        <p className="ax-note" role="status">The atlas cannot count a population that failed to load.</p>
      </div>
    )
  }
  if (!derived) {
    return (
      <div className="ax-shell">
        <p className="ax-note" role="status">Counting the population...</p>
      </div>
    )
  }
  return (
    <div className="ax-shell">
      <StormAtlas summary={derived.summary} baselineSummary={derived.baseline} selectedId={selectedId} />
      <AtlasStripPlot plot={derived.plot} label={derived.summary.headline} selectedId={selectedId} onSelectAccount={handleSelect} />
    </div>
  )
}
```

