const fs = require('node:fs')

function lineOf(text, index) {
  return text.slice(0, index).split('\n').length
}

function proseOf(file, text) {
  const prose = []
  let rest = text
  const push = (chunk, index, where) => prose.push({ file, line: lineOf(text, index), chunk, where })
  rest = rest.replace(/\/\*[\s\S]*?\*\//g, (chunk, index) => {
    push(chunk, index, 'block comment')
    return ' '
  })
  rest = rest.replace(/\/\/[^\n]*/g, (chunk, index) => {
    push(chunk, index, 'line comment')
    return ' '
  })
  const stringPattern = /'(?:[^'\\\n]|\\.)*'|"(?:[^"\\\n]|\\.)*"|`(?:[^`\\]|\\.)*`/g
  let match
  while ((match = stringPattern.exec(rest)) !== null) {
    const chunk = match[0].replace(/\$\{[^}]*\}/g, '')
    push(chunk, match.index, 'string literal')
  }
  rest = rest.replace(stringPattern, ' ')
  const jsxPattern = />([^<>{}]+)</g
  while ((match = jsxPattern.exec(rest)) !== null) {
    const chunk = match[1] ?? ''
    push(chunk, match.index, 'jsx text')
  }
  return prose
}

const file = process.argv[2]
const text = fs.readFileSync(file, 'utf8')
for (const entry of proseOf(file, text)) {
  if (entry.chunk.includes('--') || entry.chunk.includes(' - ')) {
    console.log(entry.line, entry.where, JSON.stringify(entry.chunk.slice(0, 140)))
  }
}

