import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { parseProfilesArtifact } from '../data/profiles'
import { buildAtlasPlot } from './atlasPlot'
import { IDLE_TWIST, normalizeTwist } from './shocks'
import { shockedAtlasScenario, summarizeStormAtlas } from './stormAtlas'

/** Temporary E5 timing bench, deleted after the measurement. */

const artifact = parseProfilesArtifact(
  JSON.parse(
    readFileSync(new URL('../../public/data/engine/profiles.json', import.meta.url), 'utf8'),
  ),
)
const profiles = Object.values(artifact.profiles)
const layoff = normalizeTwist({ jobLoss: true, incomeFactor: 0.55, durationMonths: 6 })

describe('atlas timing', () => {
  it('measures one twist change', () => {
    // Warm the JIT the way a first interaction would not be warmed.
    shockedAtlasScenario(profiles.slice(0, 500), IDLE_TWIST)

    const runs: Record<string, number> = {}
    for (let index = 0; index < 5; index += 1) {
      const start = performance.now()
      const scenario = shockedAtlasScenario(profiles, layoff)
      const afterTwist = performance.now()
      const summary = summarizeStormAtlas(scenario.entries, {
        scenarioLabel: scenario.scenarioLabel,
      })
      const baseline = summarizeStormAtlas(
        shockedAtlasScenario(profiles, IDLE_TWIST).entries,
      )
      const plot = buildAtlasPlot(scenario.entries)
      const end = performance.now()
      runs.twist = Number((afterTwist - start).toFixed(2))
      runs.summaryBaselinePlot = Number((end - afterTwist).toFixed(2))
      runs.total = Number((end - start).toFixed(2))
      expect(summary.total).toBe(4500)
      expect(baseline.total).toBe(4500)
      expect(plot.total).toBe(4500)
    }
    console.log('atlas derivation timing (ms):', JSON.stringify(runs))

    // Generous ceiling so the bench fails loudly only on a real
    // regression, not on a loaded CI box.
    expect(runs.total).toBeLessThan(250)
  })
})

